from .syslog_entry import SyslogEntry


class BtslogEntry(SyslogEntry):
    """
    Provides methods to parse, represent btslog entry object in readable format.
    """

    def __init__(self, btslog_timestamp, btslog_seq_nr, source_ip_addr, receiving_port=None, **kwargs):
        super(BtslogEntry, self).__init__(**kwargs)
        self.btslog_timestamp = btslog_timestamp
        self.btslog_seq_nr = btslog_seq_nr
        self.source_ip_addr = source_ip_addr
        self.receiving_port = receiving_port
